def techniques():
 return {'schema':'rtr-twin-techniques/1.0','claim':'Architecture choices and prerequisites; not certification or a claim of universal best technique.','techniques':[
 {'id':'source-qc','status':'implemented','name':'Immutable byte fingerprints, source contracts and purpose-specific admission','url':'https://stacspec.org/en/about/stac-spec/','conditions':['Hash establishes byte identity, not correctness. Native core catalog is not advertised as a certified STAC catalog.']},
 {'id':'geojson','status':'implemented','name':'WGS84 GeoJSON normalized geographic features','url':'https://www.rfc-editor.org/rfc/rfc7946','conditions':['Explicit render-frame adapter and source semantics required. Source positional accuracy stays unknown unless surveyed.']},
 {'id':'cog','status':'planned_production_adapter','name':'Cloud Optimized GeoTIFF range reads, masks and overviews','url':'https://www.ogc.org/standard/cog/','conditions':['Current batch fingerprints retained raster assets; it does not decode them as a new raster service. Source effective resolution cannot be improved by resampling.']},
 {'id':'3d-tiles','status':'planned_production_adapter','name':'OGC 3D Tiles 1.1 spatial hierarchy and semantic metadata','url':'https://docs.ogc.org/cs/22-025r4/22-025r4.html','conditions':['Actual georeferenced meshes/point clouds, tiling bounds/errors and independently tested coordinate registration required.']},
 {'id':'citygml','status':'planned_semantic_adapter','name':'CityGML 3.0 / CityJSON semantic LoD and physical asset identity','url':'https://www.ogc.org/standard/citygml/','conditions':['Building identity, parts, surfaces, source version and geometry validation required; current render parts are not CityGML compliance.']},
 {'id':'gaussian-splat','status':'planned_capture_branch','name':'COLMAP camera registration plus Gaussian splats for close visual inspection','url':'https://github.com/nerfstudio-project/gsplat','conditions':['Real overlapping multi-angle photographs, pose/scale registration, licensing and checkpoint QA required. Appearance representation is not a measurement substitute.']},
 {'id':'geoparquet','status':'planned_storage_adapter','name':'GeoParquet/Arrow analytical tables and indexed source ingestion','url':'https://geoparquet.org/releases/v1.1.0/','conditions':['This static local batch normalizes JSON; it does not operate a production GeoParquet data warehouse.']},
 {'id':'globalbuildingatlas','status':'blocked_commercial_additional_assets','name':'GlobalBuildingAtlas candidate','url':'https://github.com/zhu-xlab/GlobalBuildingAtlas','conditions':['Producer distinguishes polygon ODbL from additional polygons, heights and LoD1 under CC BY-NC 4.0. Additional NC assets are not integrated into commercial RtR solution.']} ]}
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--project',choices=['hcmc','gia-loc','all'],default='all');p.add_argument('--check',action='store_true',help='compare generated bytes; no writes');a=p.parse_args()
 items={'techniques':techniques()}
 if a.project in ['hcmc','all']:items['hcmc']=hcmc()
 if a.project in ['gia-loc','all']:items['gia-loc']=gialoc()
 failed=[]
 for name,obj in items.items():
  target=HERE/'projects'/f'{name}.json';raw=json.dumps(obj,ensure_ascii=False,indent=2,sort_keys=True)+'\n'
  if a.check:
   if not target.exists() or target.read_text()!=raw:failed.append(str(target))
  else:target.parent.mkdir(parents=True,exist_ok=True);target.write_text(raw)
  print(f'{name}: {len(obj.get("sources",obj.get("techniques",[])))} records; {"CHECK" if a.check else "WRITE"}')
 if failed:raise SystemExit('Catalog differs: '+', '.join(failed))
if __name__=='__main__':main()
